    "答疑上架后暂时不能修改；要改内容，先在「我的服务」里另发一条。": "Une consultation ne peut pas encore être modifiée une fois publiée. Pour changer le contenu, publiez-en une nouvelle dans Mes services.",
    "答疑已上架": "Consultation publiée",
    "答疑只有两种计价：按次、按小时。本平台不抽佣。": "La consultation n'a que deux tarifs : à la séance ou à l'heure. Cette plateforme ne prélève aucune commission.",
