    "「{domain}」里买家会被这样引导提问；这些内容由平台统一给定，不能改写。": "In {domain} gli acquirenti vengono guidati a fare domande così. Il testo è fissato dalla piattaforma; non puoi riscriverlo.",
    "「{term}」是执业称谓，没有对应执业资质不能这样写，改成事实性的身份描述。": "\"{term}\" è un titolo professionale regolamentato. Senza il titolo corrispondente non usarlo: descrivi il tuo ruolo in modo fattuale.",
    "「{term}」需要单独许可才能经营，平台不承接，这项服务会被退回。": "\"{term}\" richiede un'autorizzazione a parte. Questa piattaforma non se ne occupa e l'inserzione verrà respinta.",
