    "{n} 字 / 至少 30 字": "{n} ký tự / tối thiểu 30",
    "「{category}」要写清这几项；它们会展示给买家，也是有争议时核对的依据。": "Với {category}, hãy ghi rõ các mục này. Người mua nhìn thấy, và đó là căn cứ khi có tranh chấp.",
    "「{domain}」里买家会被这样引导提问；这些内容由平台统一给定，不能改写。": "Trong {domain}, người mua được hướng dẫn hỏi như vậy. Nền tảng đặt sẵn nội dung này; bạn không được sửa.",
    "「{term}」是执业称谓，没有对应执业资质不能这样写，改成事实性的身份描述。": "\"{term}\" là danh xưng nghề có giấy phép. Không có chứng chỉ tương ứng thì đừng viết vậy — mô tả vai trò bằng sự thật.",
    "「{term}」需要单独许可才能经营，平台不承接，这项服务会被退回。": "\"{term}\" cần giấy phép riêng. Nền tảng không nhận, và dịch vụ này sẽ bị trả lại.",
    "按次": "Theo lượt",
    "按次答疑要写明一次包含几轮问答": "Tính theo lượt thì ghi rõ một lượt gồm bao nhiêu vòng hỏi đáp",
    "按次计价，已写明轮次": "Tính theo lượt, đã ghi số vòng",
    "按记录的时长结算，有争议时按已发生的时长分。": "Tính theo thời gian đã ghi. Nếu tranh chấp, chia theo thời gian đã diễn ra.",
    "按小时": "Theo giờ",
    "按小时答疑要写明一小时按多少分钟计": "Tính theo giờ thì ghi rõ một giờ tính bao nhiêu phút",
    "按小时计价，已写明分钟数": "Tính theo giờ, đã ghi số phút",
